DECLARE
  l_dept_match       NUMBER;
  l_dept_no_match    NUMBER;
  l_expected         NUMBER;
  l_actual           NUMBER;
  l_failures         PLS_INTEGER := 0;
BEGIN
  SAVEPOINT test_savepoint;

  DBMS_OUTPUT.PUT_LINE('Testing HARNESS_APP.HEADCOUNT');

  -- Check 1: a department_id that matches at least one row, if one exists.
  SELECT MIN(department_id)
    INTO l_dept_match
    FROM employees
   WHERE department_id IS NOT NULL;

  IF l_dept_match IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: expected a non-null employees.department_id with at least one matching row, but found none.');
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_dept_match;

    l_actual := HARNESS_APP.headcount(l_dept_match);

    IF l_actual = l_expected THEN
      DBMS_OUTPUT.PUT_LINE('PASS: headcount(' || l_dept_match || ') expected ' || l_expected || ', actual ' || l_actual);
    ELSE
      DBMS_OUTPUT.PUT_LINE('FAIL: headcount(' || l_dept_match || ') expected ' || l_expected || ', actual ' || l_actual);
      l_failures := l_failures + 1;
    END IF;
  END IF;

  -- Check 2: a department_id that matches no row.
  -- Try to derive a value above the current maximum non-null department_id,
  -- then confirm independently that it matches no row.
  SELECT NVL(MAX(department_id), -1) + 1
    INTO l_dept_no_match
    FROM employees;

  IF l_dept_no_match IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: could not derive a non-matching department_id for testing.');
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_dept_no_match;

    IF l_expected <> 0 THEN
      DBMS_OUTPUT.PUT_LINE('FAIL: derived department_id ' || l_dept_no_match || ' was expected to match no rows, but it matched ' || l_expected || '.');
      l_failures := l_failures + 1;
    ELSE
      l_actual := HARNESS_APP.headcount(l_dept_no_match);

      IF l_actual = 0 THEN
        DBMS_OUTPUT.PUT_LINE('PASS: headcount(' || l_dept_no_match || ') expected 0, actual ' || l_actual);
      ELSE
        DBMS_OUTPUT.PUT_LINE('FAIL: headcount(' || l_dept_no_match || ') expected 0, actual ' || l_actual);
        l_failures := l_failures + 1;
      END IF;
    END IF;
  END IF;

  -- Check 3: NULL argument. The function uses department_id = p_department_id,
  -- so a NULL argument matches no row and should return 0.
  SELECT COUNT(*)
    INTO l_expected
    FROM employees
   WHERE department_id = CAST(NULL AS NUMBER);

  l_actual := HARNESS_APP.headcount(NULL);

  IF l_actual = l_expected THEN
    DBMS_OUTPUT.PUT_LINE('PASS: headcount(NULL) expected ' || l_expected || ', actual ' || l_actual);
  ELSE
    DBMS_OUTPUT.PUT_LINE('FAIL: headcount(NULL) expected ' || l_expected || ', actual ' || l_actual);
    l_failures := l_failures + 1;
  END IF;

  ROLLBACK TO test_savepoint;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(-20999, 'headcount test block reported ' || l_failures || ' failed check(s).');
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: unexpected error during headcount test block: ' || SQLERRM);
    ROLLBACK TO test_savepoint;
    RAISE;
END;
```

What each check covers:

- Check 1 calls `HARNESS_APP.headcount` for a non-null `employees.department_id` found by the block itself, if one exists. The expected value is computed independently with `SELECT COUNT(*) ... WHERE department_id = :found_value`. If no such row is found, the check prints `FAIL` and counts as a failure rather than silently skipping.

- Check 2 derives a candidate `department_id` above the current maximum non-null `department_id`, then verifies independently that it matches no rows. It then calls `HARNESS_APP.headcount` and expects `0`. If the derived value cannot be used, or if it unexpectedly matches rows, the check prints `FAIL` and counts as a failure.

- Check 3 calls `HARNESS_APP.headcount(NULL)`. Because the selected function filters with `department_id = p_department_id`, a `NULL` argument is expected to match no row and return `0`. The expected value is computed with the same equality comparison used by the function.

I have not run this block. It calls the stored unit by name and does not copy the selected function into the block.

